    "SENTRO": "Sentro",
    "CENTRO": "Sentro",
    "SAINT PAUL 1": "Saint Paul 1",
    "SAINT PAUL 2": "Saint Paul 2",
    "PUNDONGAN": "Pundongan",
    "SAGINGAN": "Sagingan",
    "CORE HOUSING": "Core Housing",
    "ABUNGAN": "Abungan",
    "CAMILING": "Camiling",
    "ALMACIGA": "Almaciga",
    "KAMAGONG": "Kamagong",
    "MAHOGANY": "Mahogany",
    "MULAWIN": "Mulawin",
    "NARRA": "Narra",
    "YAKAL 1": "Yakal 1",
    "YAKAL 2": "Yakal 2",
    "IPIL-IPIL": "Ipil-Ipil",
    "IPIL IPIL": "Ipil-Ipil",
    "BACONG": "Bacong",
    "BAKAHAN": "Bakahan",
    "DUGYAN": "Dugyan",
    "FERRY": "Ferry",
    "IYAPIT": "Iyapit",
    "KAMANDAG": "Kamandag",
    "LIMBOK": "Limbok",
    "MALACAUAYAN": "Malacauayan",
