function formatBday(bdayStr) {
  if (!bdayStr) return "1980-01-01";
  const parts = bdayStr.split(/[\/\-]/);
  if (parts.length === 3) {
    if (parts[2].length === 4) {
      // DD/MM/YYYY
      const d = parts[0].padStart(2, "0");
      const m = parts[1].padStart(2, "0");
      const y = parts[2];
      return `${y}-${m}-${d}`;
    }
  }
  return bdayStr;
}

async function main() {
  const prog = await prisma.program.findFirst({
    where: { status: "ACTIVE" },
    orderBy: { createdAt: "desc" },
  });
  if (!prog) throw new Error("No active program");

  console.log(`Reseeding exact 522 Final Masterlist Beneficiaries for Program: ${prog.programCode} (${prog.id})`);

  // Remove invalid/dummy beneficiary (e.g. Brgy. -> Street)
  try {
    const dummyBenes = await prisma.beneficiary.findMany({
      where: {
        OR: [
          { fullName: { contains: "FORMULA" } },
          { fullName: { contains: "NAME OF BENEFICIARY" } },
          { barangay: "Street" },
          { barangay: "Brgy." },
        ]
      }
    });

    for (const d of dummyBenes) {
      console.log(`Removing dummy entry: ${d.fullName} (ID: ${d.id})`);
      const pbs = await prisma.programBeneficiary.findMany({ where: { beneficiaryId: d.id } });
      for (const pb of pbs) {
        await prisma.qrCode.deleteMany({ where: { programBeneficiaryId: pb.id } });
        await prisma.orientationAttendance.deleteMany({ where: { programBeneficiaryId: pb.id } });
        await prisma.stubDistribution.deleteMany({ where: { programBeneficiaryId: pb.id } });
      }
      await prisma.programBeneficiary.deleteMany({ where: { beneficiaryId: d.id } });
      await prisma.dependent.deleteMany({ where: { beneficiaryId: d.id } });
      await prisma.beneficiary.delete({ where: { id: d.id } });
    }
  } catch (err) {
    console.error("Note on dummy cleanup:", err.message);
  }

  // Table assignment rules
  const tableRules = await prisma.tableAssignmentRule.findMany({
    where: { programId: prog.id },
    orderBy: { priority: "desc" },
  });

  const getTable = (num) => {
    for (const rule of tableRules) {
      if (num >= rule.startNumber && num <= rule.endNumber) {
        return rule.tableNumber;
      }
    }
    return `Table ${Math.ceil(num / 100)}`;
  };

  console.log("Pre-fetching existing records for fast mapping...");
  const existingBenes = await prisma.beneficiary.findMany();
  const beneByName = new Map();
  for (const b of existingBenes) {
    beneByName.set(b.fullName.trim().toUpperCase(), b);
  }

  const existingPbs = await prisma.programBeneficiary.findMany({
    where: { programId: prog.id }
  });
  const pbByBeneId = new Map();
  for (const p of existingPbs) {
    pbByBeneId.set(p.beneficiaryId, p);
  }

  const existingQrs = await prisma.qrCode.findMany({
    where: { programId: prog.id, status: "ACTIVE" }
  });
  const qrByPbId = new Map();
  for (const q of existingQrs) {
    qrByPbId.set(q.programBeneficiaryId, q);
  }

  console.log(`Starting fast upsert for ${rawData.length} beneficiaries...`);
  let processedCount = 0;

  // Process in batches of 20
  const BATCH_SIZE = 20;
  for (let i = 0; i < rawData.length; i += BATCH_SIZE) {
    const chunk = rawData.slice(i, i + BATCH_SIZE);

    await Promise.all(chunk.map(async (r) => {
      const desig = String(r[0]);
      const numInt = parseInt(desig, 10) || 1;
      const fullName = r[1].trim().toUpperCase();
      const bdayFormatted = formatBday(r[2]);
      const rawStreet = r[3] || "";
      const rawBrgy = r[4] || "Aplaya";
      const barangay = normalizeBarangayName(rawBrgy);
      const sitio = normalizeSitioName(rawStreet);

      const idType = r[5] || "NATIONAL ID";
      const idNumber = r[6] || "";
      const contact = r[7] || "";
      const beneType = r[8] || "SELF-EMPLOYED";
      const occupation = r[9] || "LABORER";
      const sex = r[10] === "F" ? "FEMALE" : "MALE";
      const civil = r[11] === "M" ? "MARRIED" : r[11] === "S" ? "SINGLE" : "WIDOWED";
      const age = r[12] || 30;

      const depName = r[13];
      const depRel = r[14];
      const depAge = r[15];
      const isPwd = r[16] === "Y";
      const isIp = r[17] === "Y";
      const isSenior = (age >= 60) || beneType.toLowerCase().includes("senior");

      const tableNumber = getTable(numInt);

      // Name parts
      let lastName = "";
      let firstName = "";
      let middleName = "";
      let extName = "";
      if (fullName.includes(",")) {
        const parts = fullName.split(",");
        lastName = parts[0].trim();
        const firstParts = (parts[1] || "").trim().split(" ");
        firstName = firstParts[0] || "";
        middleName = firstParts.slice(1).join(" ") || "";
      }

      // 1. Upsert Beneficiary
      let bene = beneByName.get(fullName);

      if (!bene) {
        bene = await prisma.beneficiary.create({
          data: {
            beneficiaryNumber: `BN-${desig.padStart(4, "0")}`,
            fullName,
            firstName,
            middleName,
            lastName,
            extensionName: extName,
            birthday: bdayFormatted,
            barangay,
            sitio,
            municipality: "Dingalan",
            province: "Aurora",
            contactNumber: contact,
            idType,
            idNumber,
            typeOfBeneficiary: beneType,
            occupation,
            sex,
            civilStatus: civil,
            age,
            isSenior,
            isPwd,
            isIp,
            is4Ps: false,
            status: "ACTIVE",
          }
        });
        beneByName.set(fullName, bene);
      } else {
        bene = await prisma.beneficiary.update({
          where: { id: bene.id },
          data: {
            beneficiaryNumber: `BN-${desig.padStart(4, "0")}`,
            birthday: bdayFormatted,
            barangay,
            sitio,
            contactNumber: contact || bene.contactNumber,
            idType: idType || bene.idType,
            idNumber: idNumber || bene.idNumber,
            typeOfBeneficiary: beneType || bene.typeOfBeneficiary,
            occupation: occupation || bene.occupation,
            sex,
            civilStatus: civil,
            age: age || bene.age,
            isSenior,
            isPwd,
            isIp,
          }
        });
        beneByName.set(fullName, bene);
      }

      // 2. Upsert ProgramBeneficiary
      let pb = pbByBeneId.get(bene.id);

      if (!pb) {
        pb = await prisma.programBeneficiary.create({
          data: {
            programId: prog.id,
            beneficiaryId: bene.id,
            designatedNumber: desig,
            tableNumber,
            slotGroup: "Main",
            participationStatus: "ACTIVE",
          }
        });
        pbByBeneId.set(bene.id, pb);
      } else {
        pb = await prisma.programBeneficiary.update({
          where: { id: pb.id },
          data: {
            designatedNumber: desig,
            tableNumber,
            participationStatus: "ACTIVE",
          }
        });
        pbByBeneId.set(bene.id, pb);
      }

      // 3. Ensure QR code exists
      let existingQr = qrByPbId.get(pb.id);
      if (!existingQr) {
        const publicToken = `TUPAD-DGL-${prog.id.substring(0, 4).toUpperCase()}-${desig.padStart(4, "0")}-${crypto.randomBytes(3).toString("hex").toUpperCase()}`;
        const tokenHash = crypto.createHash("sha256").update(publicToken).digest("hex");
        existingQr = await prisma.qrCode.create({
          data: {
            programId: prog.id,
            programBeneficiaryId: pb.id,
            publicToken,
            tokenHash,
            status: "ACTIVE",
          }
        });
        qrByPbId.set(pb.id, existingQr);
      }

      // 4. Dependent if provided
      if (depName) {
        const existingDep = await prisma.dependent.findFirst({
          where: { beneficiaryId: bene.id }
        });
        if (!existingDep) {
          await prisma.dependent.create({
            data: {
              beneficiaryId: bene.id,
              fullName: depName.trim().toUpperCase(),
              relationship: depRel || "RELATION",
              age: depAge || 25,
            }
          });
        }
      }

      processedCount++;
    }));

    console.log(`Progress: ${processedCount}/${rawData.length} processed...`);
  }

  // Ensure only the exact 522 beneficiaries are in the active program
  const validBeneIds = new Set(Array.from(beneByName.values()).map(b => b.id));
  const allCurrentPbs = await prisma.programBeneficiary.findMany({
    where: { programId: prog.id }
  });

  for (const cp of allCurrentPbs) {
    const desigNum = parseInt(cp.designatedNumber, 10);
    if (!validBeneIds.has(cp.beneficiaryId) || isNaN(desigNum) || desigNum < 1 || desigNum > 522) {
      console.log(`Removing non-masterlist ProgramBeneficiary ID: ${cp.id}, Desig: ${cp.designatedNumber}`);
      await prisma.qrCode.deleteMany({ where: { programBeneficiaryId: cp.id } });
      await prisma.programBeneficiary.delete({ where: { id: cp.id } });
    }
  }

  // Update Program total count
  const finalActiveCount = await prisma.programBeneficiary.count({
    where: { programId: prog.id, participationStatus: { not: "REPLACED" } }
  });

  await prisma.program.update({
    where: { id: prog.id },
    data: { beneficiaryCount: finalActiveCount }
  });

  console.log(`\n=== Done! Processed ${processedCount} Final Masterlist Beneficiaries ===`);
  console.log(`Total Active Beneficiaries in Program: ${finalActiveCount}`);

  // Summary by Barangay and Sitio
  const summary = await prisma.beneficiary.groupBy({
    by: ['barangay', 'sitio'],
    where: {
      programBeneficiaries: {
        some: { programId: prog.id, participationStatus: { not: "REPLACED" } }
      }
    },
    _count: { id: true }
  });

  console.log("\n=== Final Masterlist Distribution ===");
  summary.sort((a, b) => (a.barangay || "").localeCompare(b.barangay || "") || (a.sitio || "").localeCompare(b.sitio || ""))
    .forEach(s => {
      console.log(`- ${s.barangay} -> ${s.sitio}: ${s._count.id} beneficiaries`);
    });
}

main().finally(() => prisma.$disconnect());

